const d = msg.payload;

const numero = v =>
    typeof v === "number" && Number.isFinite(v);

// Impede que Injects e mensagens fora do formato sejam gravados.
if (
    !d ||
    typeof d !== "object" ||
    Array.isArray(d) ||
    typeof d.grupo !== "string" ||
    typeof d.dispositivo !== "string"
) {
    node.warn("Mensagem ignorada: nao e um objeto de sensores.");
    return null;
}

// Filtra a equipe e o dispositivo deste projeto.
if (
    d.grupo !== "grupo01" ||
    d.dispositivo !== "esp32-grupo01-01"
) {
    return null;
}

const token = env.get("INFLUX_TOKEN");

if (!token) {
    node.error(
        "INFLUX_TOKEN nao foi definido no container Node-RED."
    );
    return null;
}

const escaparTag = valor =>
    String(valor)
        .replace(/\\/g, "\\\\")
        .replace(/ /g, "\\ ")
        .replace(/,/g, "\\,")
        .replace(/=/g, "\\=");

// Limiares iniciais do projeto
const presenca =
    d.distancia_valida === true &&
    numero(d.distancia_cm) &&
    d.distancia_cm >= 2 &&
    d.distancia_cm <= 100;

const movimento =
    numero(d.amostras_aceleracao) &&
    d.amostras_aceleracao > 0 &&
    numero(d.aceleracao_desvio_pico_ms2) &&
    d.aceleracao_desvio_pico_ms2 >= 3.0;

const temperaturaValida =
    d.temperatura_valida === true &&
    numero(d.temperatura_c);

const temperaturaBaixa =
    temperaturaValida &&
    d.temperatura_c <= 15;

const temperaturaAlta =
    temperaturaValida &&
    d.temperatura_c >= 30;

const alarme =
    (presenca && movimento) ||
    temperaturaBaixa ||
    temperaturaAlta;

const campos = [];

if (temperaturaValida) {
    campos.push(`temperatura_c=${d.temperatura_c}`);
}

if (
    d.temperatura_valida === true &&
    numero(d.umidade_pct)
) {
    campos.push(`umidade_pct=${d.umidade_pct}`);
}

if (
    d.distancia_valida === true &&
    numero(d.distancia_cm)
) {
    campos.push(`distancia_cm=${d.distancia_cm}`);
}

if (
    d.amostras_aceleracao > 0 &&
    numero(d.aceleracao_desvio_pico_ms2)
) {
    campos.push(
        `movimento_pico_ms2=${d.aceleracao_desvio_pico_ms2}`
    );
}

if (campos.length === 0) {
    node.warn("Mensagem sem leituras validas. Nao foi gravada.");
    return null;
}

campos.push(`presenca=${presenca ? 1 : 0}`);
campos.push(`movimento=${movimento ? 1 : 0}`);
campos.push(`alarme=${alarme ? 1 : 0}`);

msg.headers = {
    Authorization: "Token " + token,
    "Content-Type": "text/plain; charset=utf-8"
};

msg.payload =
    `sensores,grupo=${escaparTag(d.grupo)},` +
    `dispositivo=${escaparTag(d.dispositivo)} ` +
    campos.join(",") +
    ` ${Date.now()}`;

return msg;

const d = msg.payload;

const numero = v =>
    typeof v === "number" && Number.isFinite(v);

if (
    !d ||
    typeof d !== "object" ||
    d.grupo !== "grupo01" ||
    d.dispositivo !== "esp32-grupo01-01"
) {
    return null;
}

const limites = {
    distanciaMin: 2,
    distanciaMax: 100,
    movimento: 3,
    temperaturaMin: 15,
    temperaturaMax: 30
};

const presenca =
    d.distancia_valida === true &&
    numero(d.distancia_cm) &&
    d.distancia_cm >= limites.distanciaMin &&
    d.distancia_cm <= limites.distanciaMax;

const movimento =
    d.amostras_aceleracao > 0 &&
    numero(d.aceleracao_desvio_pico_ms2) &&
    d.aceleracao_desvio_pico_ms2 >= limites.movimento;

const temperaturaValida =
    d.temperatura_valida === true &&
    numero(d.temperatura_c);

const motivos = [];

if (presenca && movimento) {
    motivos.push("presenca_e_movimento");
}

if (
    temperaturaValida &&
    d.temperatura_c <= limites.temperaturaMin
) {
    motivos.push("temperatura_baixa");
}

if (
    temperaturaValida &&
    d.temperatura_c >= limites.temperaturaMax
) {
    motivos.push("temperatura_alta");
}

if (motivos.length === 0) {
    return null;
}

const agora = Date.now();
const ultimaTentativa = context.get("ultimaTentativa") || 0;

if (agora - ultimaTentativa < 10000) {
    return null;
}

context.set("ultimaTentativa", agora);

const id = `${d.grupo}_${agora}_${d.sequencia}`;

msg.filename = `/data/files/${id}.jpg`;

msg.evento = {
    id,
    solicitado_em: new Date(agora).toISOString(),
    motivos,
    limites,
    sensores: d,
    arquivo_imagem: msg.filename
};

node.status({
    fill: "yellow",
    shape: "dot",
    text: motivos.join(", ")
});

return msg;

const b = msg.payload;

if (
    msg.statusCode !== 200 ||
    !Buffer.isBuffer(b) ||
    b.length < 4 ||
    b[0] !== 0xFF ||
    b[1] !== 0xD8
) {
    node.error(
        `Foto invalida. HTTP: ${msg.statusCode}`
    );

    return null;
}

msg.evento.recebido_em = new Date().toISOString();
msg.evento.tamanho_bytes = b.length;

return msg;

// Este nó recebe a mensagem depois da gravação da imagem.
flow.set("ultimaFoto", msg.payload);
flow.set("ultimoEventoFoto", msg.evento);

node.status({
    fill: "green",
    shape: "dot",
    text: "Imagem salva"
});

msg.filename = `/data/files/${msg.evento.id}.json`;
msg.payload = JSON.stringify(msg.evento, null, 2);

// Remove dados da resposta HTTP que não são necessários.
delete msg.headers;

return msg;

const foto = flow.get("ultimaFoto");

msg.headers = {
    "Cache-Control": "no-store"
};

if (!Buffer.isBuffer(foto)) {
    msg.statusCode = 404;
    msg.headers["Content-Type"] = "text/plain; charset=utf-8";
    msg.payload = "Ainda nao houve captura nesta execucao.";
    return msg;
}

msg.statusCode = 200;
msg.headers["Content-Type"] = "image/jpeg";
msg.payload = foto;

return msg;
